m5-6.1.solution:
def estimate_pi(n_samples, seed):
    rng = np.random.default_rng(seed)
    x = rng.uniform(-1, 1, size=n_samples)
    y = rng.uniform(-1, 1, size=n_samples)
    inside = x**2 + y**2 <= 1
    return 4 * inside.mean()

