m6-3.2.solution:
def roundtrip_npz(a, b):
    buf = io.BytesIO()
    np.savez(buf, a=a, b=b)
    buf.seek(0)
    archive = np.load(buf)
    return {"a": archive["a"], "b": archive["b"]}

